import pandas as pd
import numpy as np

# Load the data
crime_data = pd.read_csv('chunks_csv/moran_local_no2crime_crime_first_half_2018.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values by replacing with the mean of non-missing values
crime_data['value'] = crime_data['value'].fillna(crime_data['value'].mean())

# Compute neighborhood averages
neighborhood_averages = {}
for index, row in crime_data.iterrows():
    neighbors = adjacency_data[adjacency_data['borough'] == row['borough']]['neighbor'].tolist()
    neighbor_values = crime_data[crime_data['borough'].isin(neighbors)]['value'].tolist()
    neighborhood_averages[row['borough']] = np.mean(neighbor_values)

# Classify boroughs as HOT SPOT or COLD SPOT
classifications = {}
for index, row in crime_data.iterrows():
    if row['value'] > neighborhood_averages[row['borough']]:
        classifications[row['borough']] = 'HOT SPOT'
    elif row['value'] < neighborhood_averages[row['borough']]:
        classifications[row['borough']] = 'COLD SPOT'
    else:
        classifications[row['borough']] = 'NEUTRAL'

# Compute statistical significance
significance = {}
for borough, classification in classifications.items():
    if classification != 'NEUTRAL':
        crime_data['neighborhood_average'] = crime_data['borough'].apply(lambda x: neighborhood_averages[x] if x != borough else np.nan)
        diff = crime_data[crime_data['borough'] == borough]['value'] - crime_data[crime_data['borough'] == borough]['neighborhood_average']
        test_statistic = diff.mean()
        significance_measure = 1 - np.mean([np.abs(diff[i] - test_statistic) < np.abs(diff[j] - test_statistic) for i in range(len(diff)) for j in range(len(diff)) if i != j])  # permutation test
        significance[borough] = (test_statistic, significance_measure)

# Identify qualifying boroughs
qualifying_boroughs = []
for borough, classification in classifications.items():
    if classification != 'NEUTRAL':
        if significance[borough][1] < 0.05:
            qualifying_boroughs.append(f"{borough} ({classification}, statistical method={significance[borough][0]}, significance measure={significance[borough][1]})")

# Print results
print(f"data_points_used = {len(crime_data)}")
if qualifying_boroughs:
    print(f"FINAL ANSWER: {', '.join(qualifying_boroughs)}")
else:
    print("FINAL ANSWER: none")
